content:
:root {
  /* ライトテーマ（デフォルト） */
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-primary: #1e293b;
  --text-secondary: #64748b;
  --accent-color: #3b82f6;
  --accent-hover: #2563eb;
  --border-color: #e2e8f0;
  --success-color: #10b981;
  --danger-color: #ef4444;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --radius: 12px;

  /* トランジション変数 */
  --transition-duration: 0.2s;
  --transition-easing: ease;
  --transition-base: all var(--transition-duration) var(--transition-easing);
}

/* ダークモード対応の拡張 */
@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-primary: #f8fafc;
    --text-secondary: #94a3b8;
    --border-color: #334155;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -1px rgba(0, 0, 0, 0.2);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
}

body {
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
}

.header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 32px;
}

@media (min-width: 768px) {
  .header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.title {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-primary);
}

.filter-container {
  display: flex;
  gap: 8px;
  background: var(--card-bg);
  padding: 4px;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow);
}

.btn {
  background: transparent;
  border: none;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 8px;
  cursor: pointer;
  transition: var(--transition-base);
}

.btn:hover {
  color: var(--text-primary);
  background-color: var(--bg-color);
}

.btn-active {
  background-color: var(--accent-color);
  color: #ffffff;
}

.btn-active:hover {
  background-color: var(--accent-hover);
  color: #ffffff;
}

.cards-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  margin-bottom: 32px;
}

@media (min-width: 640px) {
  .cards-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .cards-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.card {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: var(--transition-base);
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
}

.card-value {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-primary);
}

.card-diff {
  font-size: 13px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 4px;
}

.card-diff.positive {
  color: var(--success-color);
}

.card-diff.negative {
  color: var(--danger-color);
}

.chart-section {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow);
  transition: var(--transition-base);
}

.chart-section h2 {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: 20px;
  color: var(--text-primary);
}

.chart-container {
  width: 100%;
  height: 350px;
}

/**
 * 月ごとの売上・客数・平均単価などの店舗パフォーマンスデータ
 */
export interface MonthlyData {
  /** 一意の識別子（オプション） */
  id?: string;
  /** 対象月（例: '1月'） */
  month: string;
  /** 対象の日付（オプション） */
  date?: string;
  /** 月間売上金額（円） */
  sales: number;
  /** 月間来店客数（人） */
  customers: number;
  /** 平均単価（円） */
  avgPrice: number;
}

import { useState } from 'react';
import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  CartesianGrid,
} from 'recharts';
import { MonthlyData } from './types';
import './index.css';

const sampleData: MonthlyData[] = [
  { month: '1月', sales: 4200000, customers: 1400, avgPrice: 3000 },
  { month: '2月', sales: 3800000, customers: 1300, avgPrice: 2923 },
  { month: '3月', sales: 4500000, customers: 1500, avgPrice: 3000 },
  { month: '4月', sales: 4900000, customers: 1600, avgPrice: 3062 },
  { month: '5月', sales: 5200000, customers: 1700, avgPrice: 3058 },
  { month: '6月', sales: 4800000, customers: 1550, avgPrice: 3096 },
  { month: '7月', sales: 5500000, customers: 1800, avgPrice: 3055 },
  { month: '8月', sales: 6100000, customers: 1950, avgPrice: 3128 },
  { month: '9月', sales: 5300000, customers: 1700, avgPrice: 3117 },
  { month: '10月', sales: 5700000, customers: 1850, avgPrice: 3081 },
  { month: '11月', sales: 6000000, customers: 1900, avgPrice: 3157 },
  { month: '12月', sales: 6800000, customers: 2100, avgPrice: 3238 },
];

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('ja-JP', { style: 'currency', currency: 'JPY' }).format(val);
};

const formatNumber = (val: number, unit: string) => {
  return `${new Intl.NumberFormat('ja-JP').format(val)}${unit}`;
};

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div style={{
        background: 'var(--card-bg)',
        border: '1px solid var(--border-color)',
        padding: '12px 16px',
        borderRadius: '8px',
        boxShadow: 'var(--shadow)'
      }}>
        <p style={{ fontWeight: 600, marginBottom: '8px', color: 'var(--text-primary)' }}>{label}</p>
        {payload.map((item: any, index: number) => (
          <p key={`item-${index}`} style={{ color: item.color || 'var(--text-secondary)', fontSize: '14px', marginBottom: '4px' }}>
            <span style={{ fontWeight: 500 }}>{item.name}: </span>
            {item.dataKey === 'customers' ? formatNumber(item.value, '人') : formatCurrency(item.value)}
          </p>
        ))}
      </div>
    );
  }
  return null;
};

export default function App() {
  const [activeMetric, setActiveMetric] = useState<'sales' | 'customers' | 'avgPrice'>('sales');

  // 安全な最新月・前月の取得
  const latest = sampleData.length > 0 ? sampleData[sampleData.length - 1] : { month: '-', sales: 0, customers: 0, avgPrice: 0 };
  const previous = sampleData.length > 1 ? sampleData[sampleData.length - 2] : latest;

  const salesDiff = previous.sales !== 0 ? ((latest.sales - previous.sales) / previous.sales) * 100 : 0;
  const customersDiff = previous.customers !== 0 ? ((latest.customers - previous.customers) / previous.customers) * 100 : 0;
  const avgPriceDiff = previous.avgPrice !== 0 ? ((latest.avgPrice - previous.avgPrice) / previous.avgPrice) * 100 : 0;

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">店舗パフォーマンスダッシュボード</h1>
        <div className="filter-container">
          <button
            className={`btn ${activeMetric === 'sales' ? 'btn-active' : ''}`}
            onClick={() => setActiveMetric('sales')}
          >
            売上
          </button>
          <button
            className={`btn ${activeMetric === 'customers' ? 'btn-active' : ''}`}
            onClick={() => setActiveMetric('customers')}
          >
            客数
          </button>
          <button
            className={`btn ${activeMetric === 'avgPrice' ? 'btn-active' : ''}`}
            onClick={() => setActiveMetric('avgPrice')}
          >
            平均単価
          </button>
        </div>
      </header>

      <div className="cards-grid">
        <div className="card">
          <span className="card-title">当月売上 ({latest.month})</span>
          <span className="card-value">{formatCurrency(latest.sales)}</span>
          <div className={`card-diff ${salesDiff >= 0 ? 'positive' : 'negative'}`}>
            {salesDiff >= 0 ? '▲' : '▼'} {Math.abs(salesDiff).toFixed(1)}% 前月比
          </div>
        </div>

        <div className="card">
          <span className="card-title">当月客数 ({latest.month})</span>
          <span className="card-value">{formatNumber(latest.customers, '人')}</span>
          <div className={`card-diff ${customersDiff >= 0 ? 'positive' : 'negative'}`}>
            {customersDiff >= 0 ? '▲' : '▼'} {Math.abs(customersDiff).toFixed(1)}% 前月比
          </div>
        </div>

        <div className="card">
          <span className="card-title">平均単価 ({latest.month})</span>
          <span className="card-value">{formatCurrency(latest.avgPrice)}</span>
          <div className={`card-diff ${avgPriceDiff >= 0 ? 'positive' : 'negative'}`}>
            {avgPriceDiff >= 0 ? '▲' : '▼'} {Math.abs(avgPriceDiff).toFixed(1)}% 前月比
          </div>
        </div>
      </div>

      <section className="chart-section">
        <h2>
          {activeMetric === 'sales' && '月別売上推移'}
          {activeMetric === 'customers' && '月別客数推移'}
          {activeMetric === 'avgPrice' && '月別平均単価推移'}
        </h2>
        <div className="chart-container">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={sampleData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="month" stroke="#64748b" />
              <YAxis stroke="#64748b" />
              <Tooltip content={<CustomTooltip />} />
              <Legend />
              {activeMetric === 'sales' && (
                <Bar dataKey="sales" name="売上" fill="#3b82f6" radius={[4, 4, 0, 0]} />
              )}
              {activeMetric === 'customers' && (
                <Bar dataKey="customers" name="客数" fill="#10b981" radius={[4, 4, 0, 0]} />
              )}
              {activeMetric === 'avgPrice' && (
                <Line
                  type="monotone"
                  dataKey="avgPrice"
                  name="平均単価"
                  stroke="#3b82f6"
                  strokeWidth={3}
                  dot={{ r: 5 }}
                />
              )}
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </section>
    </div>
  );
}
